async function call(path,opts={}){const r=await fetch(API+path,{credentials:'include',...opts,headers:{'Content-Type':'application/json',...(opts.headers||{})}});const d=await r.json();if(r.status===401&&path!=='/auth/login')window.dispatchEvent(new Event('stockflow:unauthorized'));if(!r.ok)throw Error(d.error||'Something went wrong');return d}
