function formatMovementDay(value){
 if(!value)return '—';
 const raw=String(value);
 // SQLite and PostgreSQL can return a date-only string or a timestamp. Parse
 // date-only values as local calendar dates so they do not shift by timezone.
 const dateOnly=/^\d{4}-\d{2}-\d{2}$/.test(raw);
 const parsed=dateOnly?new Date(`${raw}T12:00:00`):new Date(raw);
 if(Number.isNaN(parsed.getTime()))return '—';
 return new Intl.DateTimeFormat('en',{weekday:'short'}).format(parsed);
}
function AnimatedNumber({value}){
 const numeric=typeof value==='number'?value:Number(String(value).replaceAll(',',''));
 const valid=Number.isFinite(numeric);
 const [display,setDisplay]=useState(valid?0:value);
 const lastValue=useRef(null);
 useEffect(()=>{
  if(!valid){setDisplay(value);lastValue.current=null;return}
  const from=lastValue.current??0,to=numeric;
  lastValue.current=to;
  if(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){setDisplay(to);return}
  let frame=0,start;
  const duration=760;
  const tick=now=>{if(start===undefined)start=now;const progress=Math.min(1,(now-start)/duration);const eased=1-Math.pow(1-progress,3);setDisplay(Math.round(from+(to-from)*eased));if(progress<1)frame=requestAnimationFrame(tick)};
  frame=requestAnimationFrame(tick);
  return()=>cancelAnimationFrame(frame);
 },[numeric,valid,value]);
 return <b className="stat-value" aria-live="off">{valid?Number(display).toLocaleString():value}</b>;
}
