 async function load(){try{const[d,p,w,i,t]=await Promise.all([call(`/dashboard?days=${movementDays}`),call('/products'),call('/warehouses'),call('/inventory'),call('/transactions')]);setDash(d);setProducts(p);setWarehouses(w);setInventory(i);setTx(t);if(user.role==='admin'){const[s,o]=await Promise.all([call('/suppliers'),call('/purchase-orders')]);setSuppliers(s);setOrders(o)}}catch(e){setToast(e.message.includes('sign in')?'Your session ended. Please refresh to sign in again.':`Could not connect to server: ${e.message}`)}}useEffect(()=>{load();const id=setInterval(load,15000);return()=>{clearInterval(id);if(modalCloseTimer.current)window.clearTimeout(modalCloseTimer.current)}},[movementDays]);const categories=useMemo(()=>[...new Set(products.map(p=>p.category).filter(Boolean))].sort((a,b)=>a.localeCompare(b)),[products]);const filtered=useMemo(()=>products.filter(p=>{const matchesQuery=`${p.name} ${p.sku} ${p.category} ${p.supplier_name||''}`.toLowerCase().includes(query.trim().toLowerCase());const matchesCategory=!categoryFilter||p.category===categoryFilter;const quantity=Number(p.quantity)||0,reorder=Number(p.reorder_level)||0;const matchesStatus=stockFilter==='all'||(stockFilter==='out'&&quantity<=0)||(stockFilter==='low'&&quantity>0&&quantity<=reorder)||(stockFilter==='healthy'&&quantity>reorder);return matchesQuery&&matchesCategory&&matchesStatus}),[products,query,categoryFilter,stockFilter]);
